/* Layout decisions follow the subject of each authored module. No copy or image is replaced. */
window.ChaoReading=layout=>{
 const plan={"urban": {"context-work": "evidence", "context-field": "field", "context-tourism": "comparison", "research-personas": "voices", "research-journeys": "journeys", "strategy-concept": "thesis", "strategy-visitor": "task", "strategy-worker": "task", "strategy-blueprint": "blueprint", "making-principle": "comparison", "making-assembly": "build", "interaction-feedback": "states", "design-brand": "identity", "design-core": "screens", "design-community": "screens", "design-contexts": "field", "scenario-space": "feature", "scenario-visitor": "storyboard", "scenario-worker": "storyboard", "outcome-synthesis": "feature", "outcome-limits": "reflection"}, "plastic": {"production": "evidence", "microplastic-environments": "comparison", "waste-routes": "comparison", "existing-methods": "comparison", "existing-limit": "thesis", "interviews": "voices", "coexistence": "collage", "future-deduction": "storyboard", "plastic-storyboard": "storyboard", "concept-moodboard": "collage", "shape-studies": "comparison", "shell-assembly": "build", "assembled-check": "comparison", "control-states": "technical", "completed-machine": "feature", "final-details": "components", "instruction": "storyboard", "encounter": "feature"}, "azure": {"research-indicators": "evidence", "yushan-fieldwork": "field", "other-coast-context": "field", "household-waste-evidence": "evidence", "persistent-marine-litter": "field", "other-island-evidence": "evidence", "awareness-action-gap": "thesis", "interview-management": "voices", "interview-cleaner": "voices", "insight-definition": "reflection", "media-comparison": "comparison", "card-architecture": "comparison", "prototype-card-examples": "cards", "round-rules": "rules", "rulebook": "artifact", "digital-board": "artifact", "digital-card-set": "cards", "digital-pieces": "components", "play-sessions": "build", "questionnaires-and-feedback": "feedback", "complete-physical-kit": "feature", "physical-component-usage": "components", "social-storyboard": "storyboard", "social-partnership-references": "comparison", "social-service-prototype": "screens"}, "armor": {"education-context": "evidence", "brush-grip": "annotation", "sketch-grip": "annotation", "user-voices": "voices", "yong-movement": "movement", "hatching-movement": "movement", "grip-prototypes": "iterations", "prototype-comparison": "comparison", "subculture-context": "comparison", "metal-moodboard": "materials", "decorated-concept": "comparison", "physical-making": "build", "interaction-intent": "task", "sensor-prototype": "technical", "praise-language": "collage", "control-code": "code", "final-object": "feature", "story-situation": "storyboard"}}[document.body.dataset.case]||{};
 layout.querySelectorAll('.editorial-block').forEach(block=>{
  const content=block.querySelector('.ed-block-content');if(!content||content.querySelector('.reading-copy'))return;
  block.dataset.reading=plan[block.id]||'comparison';
  const copy=document.createElement('div'),evidence=document.createElement('div');copy.className='reading-copy';evidence.className='reading-evidence';
  [...content.children].forEach(n=>{if(n.matches('.ed-block-heading,.ed-copy'))copy.append(n);else if(!n.matches('.ed-notes'))evidence.append(n)});
  content.prepend(copy,evidence);
  if(!evidence.children.length)block.dataset.reading='reflection';
 });
 // Spatial diagrams form one drawing set; field photographs and city map form separate evidence sets.
 const field=layout.querySelector('#context-field .ed-grid');if(field){const figures=[...field.children];field.classList.add('reading-field-sets');for(const [name,start,end] of [['drawing-set',0,3],['site-set',3,8],['city-map',8,9]]){const group=document.createElement('div');group.className=name;figures.slice(start,end).forEach(f=>group.append(f));field.append(group)}}
 // Separate the two drawing techniques while retaining every sketch/model pairing in order.
 const pairs=layout.querySelector('#grip-prototypes .ed-prototype-pairs');if(pairs){const items=[...pairs.children];for(const [label,start] of [['素描握持 / SKETCHING',0],['毛笔握持 / CALLIGRAPHY',5]]){const set=document.createElement('section');set.className='reading-iteration-set';const h=document.createElement('h4');h.textContent=label;const row=document.createElement('div');row.className='reading-iteration-row';items.slice(start,start+5).forEach(n=>row.append(n));set.append(h,row);pairs.append(set)}}
 layout.querySelectorAll('.ed-task-sequence,.ed-storyboard').forEach(sequence=>{[...sequence.children].forEach((n,i)=>{n.style.setProperty('--step-index',i+1)})});
};
